if (!function_exists('uiKpi')) {
    /** Dashboard stat card: label + big number + caption, soft icon tile top-right. $tint = tailwind colour name. */
    function uiKpi(string $href, string $label, string $value, string $sub, string $icon, string $tint = 'indigo', string $valueClass = 'text-slate-900'): string {
        $tag = $href !== '' ? 'a href="' . $href . '"' : 'div';
        $end = $href !== '' ? 'a' : 'div';
        return '<' . $tag . ' class="block bg-white rounded-2xl border border-slate-200 p-4 shadow-sm hover:shadow-md hover:border-' . $tint . '-300 transition">'
            . '<div class="flex items-start justify-between gap-2"><div class="min-w-0">'
            . '<div class="text-[11px] font-semibold uppercase tracking-wide text-slate-500">' . h($label) . '</div>'
            . '<div class="mt-1.5 text-lg sm:text-2xl font-bold whitespace-nowrap ' . $valueClass . '">' . h($value) . '</div></div>'
            . '<div class="w-9 h-9 rounded-xl bg-' . $tint . '-50 text-' . $tint . '-600 flex items-center justify-center">' . uiIcon($icon, 'w-5 h-5') . '</div></div>'
            . '<div class="mt-1 text-xs text-slate-500">' . h($sub) . '</div></' . $end . '>';
    }
}

if (!function_exists('kpiMoney')) {
    /** Whole-rupee amount for stat cards (paise just crowd a phone-width card); lists keep formatCurrency(). */
    function kpiMoney(float $v): string { return '₹' . number_format($v, 0); }
}

